SELECT 'batch_014_3cc00b92_wav_05' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-21b7d621-482','sm-upload-342fe6c2-97a','sm-upload-6e85a152-b10','sm-upload-8b0078a9-701','sm-upload-a4b6dd5d-b13') AND album_id='al-725a42450daa5e1b1472c6d73cc00b92') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-21b7d621-482','sm-upload-342fe6c2-97a','sm-upload-6e85a152-b10','sm-upload-8b0078a9-701','sm-upload-a4b6dd5d-b13') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-725a42450daa5e1b1472c6d73cc00b92' AND name='花と約束') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-725a42450daa5e1b1472c6d73cc00b92') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-725a42450daa5e1b1472c6d73cc00b92') AS calculated_size;
